def max_pair(pair):
    a, b = pair
    if a > b:
        return a
    elif b > a:
        return b
    else:
        return 'Equal'

print(max_pair((10, 10)))

def sum_pairs(pairs):
    return sum(a + b for a, b in pairs)

pairs = [(1, 2), (3, 4), (5, 6)]
print(sum_pairs(pairs))

def unpack_coordinates(point):
    x, y = point
    return {'x': x, 'y': y}

# Example usage
print(unpack_coordinates((10, 20)))

def summarize_record(record):
    name, *scores, age = record
    return {'name': name, 'scores': scores, 'age': age}

print(summarize_record(('Alice', 88, 92, 25)))

def extract_evens(data):
    evens = []
    for num in data:
        evens.append(num)
    return evens

print(extract_evens((1, 2, 3, 4, 5, 6)))

def analyze_waypoints(waypoints):
    total_alt = 0
    latest_ts = ''
    for lat, lon, alt, ts in waypoints:
        total_alt += alt
        if ts > latest_ts:
            latest_ts = ts
    count = len(waypoints)
    return {
        'average_altitude': total_alt / count if count else 0,
        'latest_timestamp': latest_ts
    }

waypoints = [(34.05, -118.24, 120, '2024-01-01T10:00'), (40.71, -74.00, 150, '2024-01-02T12:00')]
print(analyze_waypoints(waypoints))
